param([ValidateSet('baseline','lanczos','sharpen')][string]$Mode='baseline',[ValidateSet(2,3,4)][int]$Zoom=2)
$repo=Resolve-Path (Join-Path $PSScriptRoot '..\..');$exe=Join-Path $repo 'app\build\Release\visual_app.exe';$map=@{baseline=0;lanczos=2;sharpen=3};Get-Process visual_app -ErrorAction SilentlyContinue|Stop-Process -Force;Start-Sleep -Milliseconds 500;$stamp=Get-Date -Format 'yyyy-MM-dd_HH-mm-ss';$log=Join-Path $repo "lab\benchmarks\raster_reconstruction\runs\human_$($Mode)_$($Zoom)x_$stamp.csv";Start-Process $exe -ArgumentList @('--zoom',"$Zoom",'--reconstruction',"$($map[$Mode])",'--log',$log)|Out-Null;Write-Output "Vision comparison running: $Mode at ${Zoom}x"
